<?php
namespace App\Services\Payments;
use App\Models\CustomerPayment;use App\Models\Sale;use App\Services\Accounting\AccountingService;use App\Services\CustomerLedgerService;use App\Support\DocumentNumber;use Illuminate\Support\Facades\DB;use RuntimeException;
class CustomerPaymentService
{
    public function __construct(private CustomerLedgerService $ledger,private AccountingService $accounting){}
    public function create(array $data): CustomerPayment{return DB::transaction(function()use($data){$amount=(float)$data['amount'];if($amount<=0)throw new RuntimeException('Payment amount must be greater than zero.');$sale=null;if(!empty($data['sale_id'])){$sale=Sale::query()->lockForUpdate()->findOrFail($data['sale_id']);if($sale->customer_id!=(int)$data['customer_id'])throw new RuntimeException('Invoice does not belong to selected customer.');if($amount>(float)$sale->due_amount)throw new RuntimeException('Payment exceeds invoice due amount.');}$p=CustomerPayment::create(['payment_no'=>DocumentNumber::temporary('REC'),'customer_id'=>$data['customer_id'],'sale_id'=>$data['sale_id']??null,'account_id'=>$data['account_id'],'payment_date'=>$data['payment_date'],'amount'=>$amount,'method'=>$data['method']??'cash','reference'=>$data['reference']??null,'notes'=>$data['notes']??null,'status'=>'posted','created_by'=>auth()->id()]);$p->update(['payment_no'=>DocumentNumber::final('REC',$p->id)]);$p->load('customer','account');$this->ledger->credit($p->customer,$amount,'payment',$p->payment_no,'Customer payment','customer_payment',$p->id,$p->payment_date->toDateString());$this->accounting->post('customer_payment',$p->id,$p->payment_no,$p->payment_date->toDateString(),'Customer payment '.$p->payment_no,[['account_id'=>$p->account_id,'debit'=>$amount,'credit'=>0],['account_code'=>'1100','debit'=>0,'credit'=>$amount,'party_type'=>'customer','party_id'=>$p->customer_id]]);if($sale){$sale->paid_amount=(float)$sale->paid_amount+$amount;$sale->due_amount=max(0,(float)$sale->grand_total-(float)$sale->paid_amount);$sale->save();}return $p;});}
}
